'use strict';
const{chromium,firefox}=require('playwright');
const URL=process.env.FORMATX_TEST_URL||'http://127.0.0.1:4178/scifi-ui/index.html';
function ok(value,message){if(!value)throw new Error(message)}
async function waitIntro(page,timeout=7000){await page.waitForFunction(()=>{const r=document.documentElement,o=document.getElementById('formatx-event-horizon');return r.classList.contains('fx-intro-complete')&&!r.classList.contains('fx-intro-running')&&(!o||o.hidden)},null,{timeout})}
async function waitApex(page){await page.waitForFunction(()=>document.documentElement.dataset.fxApex==='ready',null,{timeout:5000})}
async function state(page){return page.evaluate(()=>{const ids=[...document.querySelectorAll('[id]')].map(e=>e.id),dupes=ids.filter((id,i)=>ids.indexOf(id)!==i),canvas=document.getElementById('fx-apex-canvas'),particles=document.getElementById('fx-particle-canvas');return{renderer:document.documentElement.dataset.fxRenderer,infinite:document.documentElement.dataset.fxInfinite,loops:Number(document.documentElement.dataset.fxLoopCount||0),scene:document.documentElement.dataset.fxScene,flow:document.documentElement.dataset.fxFlow,canvas:[canvas?.width||0,canvas?.height||0],particles:[particles?.width||0,particles?.height||0],clone:document.querySelectorAll('[data-loop-clone]').length,toggle:document.querySelectorAll('.loop-toggle').length,rail:document.querySelectorAll('.fx-rail').length,old:document.querySelectorAll('.reference-commerce,.fx-site-ambient,.fx-system-rail').length,overflow:Math.max(document.documentElement.scrollWidth,document.body.scrollWidth)-innerWidth,dupes,styles:[...document.styleSheets].map(s=>s.href||'').join('|'),scripts:[...document.scripts].map(s=>s.src||'').join('|')}})}
async function desktop(type,name){const browser=await type.launch({headless:true});try{const context=await browser.newContext({viewport:{width:1440,height:960},locale:'hu-HU',colorScheme:'dark'}),page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.goto(URL+'?lang=hu',{waitUntil:'domcontentloaded'});await waitIntro(page);await waitApex(page);let s=await state(page);ok(!errors.length,name+': '+errors.join(' | '));ok(['webgl2','canvas2d'].includes(s.renderer),name+': renderer '+s.renderer);ok(s.infinite==='ready'&&s.clone===1&&s.toggle===1,name+': infinite '+JSON.stringify(s));ok(s.rail===1&&s.old===0,name+': runtime architecture');ok(!s.dupes.length,name+': duplicate IDs '+s.dupes);ok(s.canvas[0]>600&&s.canvas[1]>500,name+': canvas');ok(s.overflow<=1,name+': overflow '+s.overflow);ok(s.styles.includes('formatx-apex.css')&&!/formatx-igloo|reference-commerce|professional-sections/.test(s.styles),name+': styles');ok(s.scripts.includes('formatx-apex.js')&&!/formatx-igloo|landing\.js|pricing-sync/.test(s.scripts),name+': scripts');await page.locator('[data-flow="2"]').scrollIntoViewIfNeeded();await page.waitForFunction(()=>document.documentElement.dataset.fxFlow==='2');await page.locator('[data-language="en"]').click();await page.waitForFunction(()=>document.documentElement.lang==='en');ok((await page.locator('#experience-title').textContent()).includes('One operation'),name+': language');await page.locator('[data-currency="EUR"]').click();await page.waitForFunction(()=>document.getElementById('preview-main-price')?.textContent.includes('44'));ok((await page.locator('#preview-checkout-link').getAttribute('href')).includes('currency=EUR'),name+': checkout');await page.locator('#resources').scrollIntoViewIfNeeded();await page.waitForTimeout(300);s=await state(page);ok(s.particles[0]>500&&s.particles[1]>250,name+': particles');for(let cycle=1;cycle<=2;cycle++){const top=await page.locator('[data-loop-clone]').evaluate(n=>n.offsetTop);await page.evaluate(y=>scrollTo({top:y+8,behavior:'auto'}),top);await page.waitForFunction(expected=>Number(document.documentElement.dataset.fxLoopCount||0)>=expected&&scrollY<document.getElementById('experience').offsetTop,cycle,{timeout:3000})}s=await state(page);ok(s.loops>=2,name+': loop count '+s.loops);ok(s.overflow<=1,name+': loop overflow');console.log(JSON.stringify({case:name,state:s}));await context.close()}finally{await browser.close()}}
async function skip(){const b=await chromium.launch({headless:true});try{const p=await b.newPage({viewport:{width:1280,height:840}});await p.goto(URL,{waitUntil:'domcontentloaded'});const button=p.locator('.fx-intro-skip');await button.waitFor({state:'visible',timeout:2600});const start=Date.now();await button.click();await waitIntro(p,1900);await waitApex(p);ok(Date.now()-start<1800,'skip too slow')}finally{await b.close()}}
async function reduced(){const b=await chromium.launch({headless:true});try{const c=await b.newContext({viewport:{width:1180,height:820},reducedMotion:'reduce'}),p=await c.newPage();await p.goto(URL,{waitUntil:'domcontentloaded'});await waitIntro(p,1900);await waitApex(p);const s=await state(p);ok(s.infinite==='reduced-motion-disabled'&&s.clone===0&&s.toggle===0,'reduced infinite');ok(s.overflow<=1,'reduced overflow');await c.close()}finally{await b.close()}}
async function mobile(){const b=await chromium.launch({headless:true});try{const c=await b.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:2}),p=await c.newPage(),errors=[];p.on('pageerror',e=>errors.push(String(e)));await p.goto(URL,{waitUntil:'domcontentloaded'});await waitIntro(p);await waitApex(p);const s=await state(p);ok(!errors.length,'mobile errors '+errors);ok(s.canvas[0]>=380&&s.canvas[1]>=800,'mobile canvas');ok(s.infinite==='ready'&&s.clone===1,'mobile infinite');ok(s.overflow<=1,'mobile overflow '+s.overflow);await p.locator('#menu-toggle').click();ok(await p.locator('#main-nav').evaluate(n=>n.classList.contains('open')),'mobile menu');await c.close()}finally{await b.close()}}
(async()=>{await desktop(chromium,'chromium');await desktop(firefox,'firefox');await skip();await reduced();await mobile()})().catch(e=>{console.error(e.stack||e);process.exit(1)});